   331→            ICappedArrayPool? bufferPool = null)
   332→        {
   333→            if (NodeType != NodeType.Unknown) return;
   334→
   335→            try
   336→            {
   337→                ResolveUnknownNode(tree, path, readFlags, bufferPool);
