   404→        /// <summary>
   405→        /// Highly optimized
   406→        /// </summary>
   407→        public bool TryResolveNode(ITrieNodeResolver tree, ref TreePath path, ReadFlags readFlags = ReadFlags.None,
   408→            ICappedArrayPool? bufferPool = null)
   409→        {
   410→            try
   411→            {
   412→                SpanSource rlp = _rlp;
   413→                if (NodeType == NodeType.Unknown)
   414→                {
   415→                    if (rlp.IsNull)
   416→                    {
   417→                        Hash256 keccak = Keccak;
   418→                        if (keccak is null)
   419→                        {
   420→                            return false;
   421→                        }
   422→
   423→                        var fullRlp = tree.TryLoadRlp(path, keccak, readFlags);
   424→
   425→                        if (fullRlp is null)
   426→                        {
   427→                            return false;
   428→                        }
   429→
   430→                        _rlp = rlp = new SpanSource(fullRlp);
   431→                        IsPersisted = true;
   432→                    }
   433→                }
   434→                else
   435→                {
   436→                    return true;
   437→                }
   438→
   439→                return DecodeRlp(new ValueRlpStream(rlp), bufferPool, out _);
   440→            }
   441→            catch (RlpException)
   442→            {
