   447→        private bool DecodeRlp(ValueRlpStream rlpStream, ICappedArrayPool bufferPool, out int itemsCount)
   448→        {
   449→            Metrics.TreeNodeRlpDecodings++;
   450→
   451→            rlpStream.ReadSequenceLength();
   452→
   453→            // micro optimization to prevent searches beyond 3 items for branches (search up to three)
   454→            int numberOfItems = itemsCount = rlpStream.PeekNumberOfItemsRemaining(null, 3);
   455→
   456→            if (numberOfItems < 2)
   457→            {
   458→                return false;
   459→            }
   460→            else if (numberOfItems > 2)
   461→            {
   462→                _nodeData = new BranchData();
   463→            }
   464→            else
   465→            {
   466→                ReadOnlySpan<byte> valueSpan = rlpStream.DecodeByteArraySpan();
   467→                (byte[] key, bool isLeaf) = HexPrefix.FromBytes(valueSpan);
   468→                if (isLeaf)
   469→                {
   470→                    valueSpan = rlpStream.DecodeByteArraySpan();
   471→                    SpanSource buffer = bufferPool.SafeRentBuffer(valueSpan.Length);
   472→                    valueSpan.CopyTo(buffer.Span);
   473→                    _nodeData = new LeafData(key, buffer);
   474→                }
   475→                else
   476→                {
   477→                    _nodeData = new ExtensionData(key);
   478→                }
   479→            }
   480→
   481→            return true;
   482→        }
