   498→        public Hash256? GenerateKey(ITrieNodeResolver tree, ref TreePath path,
   499→            ICappedArrayPool? bufferPool = null, bool canBeParallel = true)
   500→        {
   501→            bool isRoot = path.Length == 0;
   502→            SpanSource rlp = _rlp;
   503→            if (rlp.IsNull || IsDirty)
   504→            {
   505→                SpanSource oldRlp = rlp.IsNotNull ? rlp : SpanSource.Empty;
   506→                SpanSource fullRlp = NodeType == NodeType.Branch
   507→                    ? TrieNodeDecoder.RlpEncodeBranch(this, tree, ref path, bufferPool,
   508→                        canBeParallel: isRoot && canBeParallel)
   509→                    : RlpEncode(tree, ref path, bufferPool);
   510→
   511→                if (oldRlp.IsNotNullOrEmpty)
   512→                {
   513→                    bufferPool.SafeReturnBuffer(oldRlp);
   514→                }
   515→
   516→                _rlp = rlp = fullRlp;
   517→            }
   518→
   519→            /* nodes that are descendants of other nodes are stored inline
   520→             * if their serialized length is less than Keccak length
   521→             * */
   522→            if (rlp.Length >= 32 || isRoot)
   523→            {
   524→                Metrics.TreeNodeHashCalculations++;
   525→                return Nethermind.Core.Crypto.Keccak.Compute(rlp.Span);
   526→            }
   527→
   528→            return null;
   529→        }
