   531→        internal SpanSource RlpEncode(ITrieNodeResolver tree, ref TreePath path, ICappedArrayPool? bufferPool = null)
   532→        {
   533→            return NodeType switch
   534→            {
   535→                NodeType.Branch => TrieNodeDecoder.RlpEncodeBranch(this, tree, ref path, bufferPool,
   536→                    canBeParallel: false),
   537→                NodeType.Extension => TrieNodeDecoder.EncodeExtension(this, tree, ref path, bufferPool),
   538→                NodeType.Leaf => TrieNodeDecoder.EncodeLeaf(this, bufferPool),
   539→                _ => ThrowUnhandledNodeType(this)
   540→            };
