   671→        public TrieNode? GetChildWithChildPath(ITrieNodeResolver tree, ref TreePath childPath, int childIndex)
   672→        {
   673→            /* extensions store value before the child while branches store children before the value
   674→             * so just to treat them in the same way we update index on extensions
   675→             */
   676→            childIndex = IsExtension ? childIndex + 1 : childIndex;
   677→            object childOrRef = ResolveChildWithChildPath(tree, ref childPath, childIndex);
