   841→        /// <summary>
   842→        /// Imagine a branch like this:
   843→        ///        B
   844→        /// ||||||||||||||||
   845→        /// -T--TP-K--P--TT-
   846→        /// where T is a transient child (not yet persisted) and P is a persisted child node and K is node hash
   847→        /// After calling this method with <paramref name="skipPersisted"/> == <value>false</value> you will end up with
   848→        ///        B
   849→        /// ||||||||||||||||
   850→        /// -A--AA-K--A--AA-
   851→        /// where A is a <see cref="TrieNode"/> on which the <paramref name="action"/> was invoked.
   852→        /// After calling this method with <paramref name="skipPersisted"/> == <value>true</value> you will end up with
   853→        ///        B
   854→        /// ||||||||||||||||
   855→        /// -A--AP-K--P--AA-
   856→        /// where A is a <see cref="TrieNode"/> on which the <paramref name="action"/> was invoked.
   857→        /// Note that nodes referenced by hash are not called.
   858→        /// </summary>
   859→        public void CallRecursively(
   860→            Action<TrieNode, Hash256?, TreePath> action,
   861→            Hash256? storageAddress,
   862→            ref TreePath currentPath,
   863→            ITrieNodeResolver resolver,
   864→            bool skipPersisted,
   865→            in ILogger logger,
   866→            int maxPathLength = Int32.MaxValue,
   867→            bool resolveStorageRoot = true)
   868→        {
   869→            if (skipPersisted && IsPersisted)
   870→            {
   871→                if (logger.IsTrace) logger.Trace($"Skipping {this} - already persisted");
   872→                return;
   873→            }
   874→
   875→            if (currentPath.Length >= maxPathLength)
   876→            {
   877→                action(this, storageAddress, currentPath);
   878→                return;
   879→            }
   880→
   881→            if (_nodeData is BranchData branchData)
   882→            {
   883→                ref readonly var data = ref branchData.Branches;
   884→                int previousLength = AppendChildPath(ref currentPath, 0);
   885→                for (int i = 0; i < BranchArray.Length; i++)
   886→                {
   887→                    if (data[i] is TrieNode child)
   888→                    {
   889→                        if (logger.IsTrace) logger.Trace($"Persist recursively on child {i} {child} of {this}");
   890→                        currentPath.SetLast(i);
   891→                        child.CallRecursively(action, storageAddress, ref currentPath, resolver, skipPersisted, logger,
   892→                            maxPathLength, resolveStorageRoot);
   893→                    }
   894→                }
   895→
   896→                currentPath.TruncateMut(previousLength);
   897→            }
   898→            else if (_nodeData is ExtensionData extensionData)
   899→            {
   900→                if (extensionData.Value is TrieNode child)
   901→                {
   902→                    if (logger.IsTrace) logger.Trace($"Persist recursively on child 0 {child} of {this}");
   903→                    int previousLength = AppendChildPath(ref currentPath, 0);
   904→                    child.CallRecursively(action, storageAddress, ref currentPath, resolver, skipPersisted, logger,
   905→                        maxPathLength, resolveStorageRoot);
   906→                    currentPath.TruncateMut(previousLength);
   907→                }
   908→            }
   909→            else if (_nodeData is LeafData leafData)
   910→            {
   911→                TrieNode? storageRoot = leafData.StorageRoot;
   912→                if (resolveStorageRoot && (storageRoot is not null ||
   913→                                           TryResolveStorageRoot(resolver, ref currentPath, out storageRoot)))
   914→                {
   915→                    if (logger.IsTrace)
   916→                        logger.Trace($"Persist recursively on storage root {leafData.StorageRoot} of {this}");
   917→                    Hash256 storagePathAddr;
   918→                    using (currentPath.ScopedAppend(Key))
   919→                    {
   920→                        if (currentPath.Length != 64)
   921→                            throw new TrieException(
   922→                                $"unexpected storage path length. Total nibble count should add up to 64. Got {currentPath.Length}.");
   923→                        storagePathAddr = currentPath.Path.ToCommitment();
   924→                    }
   925→
   926→                    TreePath emptyPath = TreePath.Empty;
   927→                    storageRoot!.CallRecursively(
   928→                        action,
   929→                        storagePathAddr,
   930→                        ref emptyPath,
   931→                        resolver.GetStorageTrieNodeResolver(storagePathAddr),
   932→                        skipPersisted,
   933→                        logger);
   934→                }
   935→            }
   936→
   937→            action(this, storageAddress, currentPath);
   938→        }
