   940→        public ValueTask CallRecursivelyAsync(
   941→            Func<TrieNode, Hash256?, TreePath, ValueTask> action,
   942→            Hash256? storageAddress,
   943→            ref TreePath currentPath,
   944→            ITrieNodeResolver resolver,
   945→            ILogger logger)
   946→        {
   947→            if (IsPersisted)
   948→            {
   949→                if (logger.IsTrace) logger.Trace($"Skipping {this} - already persisted");
   950→                return default;
   951→            }
