  1050→        /// <summary>
  1051→        /// Imagine a branch like this:
  1052→        ///        B
  1053→        /// ||||||||||||||||
  1054→        /// -T--TP----P--TT-
  1055→        /// where T is a transient child (not yet persisted) and P is a persisted child node
  1056→        /// After calling this method you will end up with
  1057→        ///        B
  1058→        /// ||||||||||||||||
  1059→        /// -T--T?----?--TT-
  1060→        /// where ? stands for an unresolved child (unresolved child is one for which we know the hash in RLP
  1061→        /// and for which we do not have an in-memory .NET object representation - TrieNode)
  1062→        /// Unresolved child can be resolved by calling ResolveChild(child_index).
  1063→        /// </summary>
  1064→        /// <param name="maxLevelsDeep">How many levels deep we will be pruning the child nodes.</param>
  1065→        public void PrunePersistedRecursively(int maxLevelsDeep)
  1066→        {
  1067→            maxLevelsDeep--;
  1068→            if (_nodeData is not LeafData leafData)
  1069→            {
  1070→                if (_nodeData is BranchData branchData)
  1071→                {
  1072→                    ref readonly var data = ref branchData.Branches;
  1073→                    for (int i = 0; i < BranchArray.Length; i++)
  1074→                    {
  1075→                        object o = data[i];
  1076→                        if (o is TrieNode child)
  1077→                        {
  1078→                            if (child.IsPersisted)
  1079→                            {
  1080→                                Pruning.Metrics.DeepPrunedPersistedNodesCount++;
  1081→                                UnresolveChild(i);
  1082→                            }
  1083→                            else if (maxLevelsDeep != 0)
  1084→                            {
  1085→                                child.PrunePersistedRecursively(maxLevelsDeep);
  1086→                            }
  1087→                        }
  1088→                    }
  1089→                }
  1090→                else if (_nodeData is ExtensionData extension)
  1091→                {
  1092→                    if (extension.Value is TrieNode child)
  1093→                    {
  1094→                        if (child.IsPersisted)
  1095→                        {
  1096→                            Pruning.Metrics.DeepPrunedPersistedNodesCount++;
  1097→                            UnresolveChild(0);
  1098→                        }
  1099→                        else if (maxLevelsDeep != 0)
  1100→                        {
  1101→                            child.PrunePersistedRecursively(maxLevelsDeep);
  1102→                        }
  1103→                    }
  1104→                }
  1105→            }
  1106→            else if (leafData.StorageRoot?.IsPersisted == true)
  1107→            {
  1108→                leafData.StorageRoot = null;
  1109→            }
  1110→
  1111→            // else
  1112→            // {
  1113→            //     // we assume that the storage root will get resolved during persistence even if not persisted yet
  1114→            //     // if this is not true then the code above that is commented out would be critical to call isntead
  1115→            //     _storageRoot = null;
  1116→            // }
  1117→        }
