  1119→        internal bool TryResolveStorageRoot(ITrieNodeResolver resolver, ref TreePath currentPath,
  1120→            out TrieNode? storageRoot)
  1121→        {
  1122→            bool hasStorage = false;
  1123→
  1124→            if (_nodeData is LeafData data)
  1125→            {
  1126→                storageRoot = data.StorageRoot;
  1127→                if (storageRoot is not null)
  1128→                {
  1129→                    hasStorage = true;
  1130→                }
  1131→                else if (Value.Length > 64) // if not a storage leaf
  1132→                {
  1133→                    Rlp.ValueDecoderContext valueContext = Value.Span.AsRlpValueContext();
  1134→                    Hash256 storageRootKey = _accountDecoder.DecodeStorageRootOnly(ref valueContext);
  1135→                    if (storageRootKey != Nethermind.Core.Crypto.Keccak.EmptyTreeHash)
  1136→                    {
  1137→                        Hash256 storagePath;
  1138→                        using (currentPath.ScopedAppend(Key))
  1139→                        {
  1140→                            storagePath = currentPath.Path.ToCommitment();
  1141→                        }
  1142→
  1143→                        hasStorage = true;
  1144→                        TreePath emptyPath = TreePath.Empty;
  1145→                        data.StorageRoot = storageRoot = resolver.GetStorageTrieNodeResolver(storagePath)
  1146→                            .FindCachedOrUnknown(in emptyPath, storageRootKey);
  1147→                    }
  1148→                }
  1149→            }
  1150→            else
  1151→            {
  1152→                storageRoot = null;
  1153→            }
  1154→
  1155→            return hasStorage;
  1156→        }
