  1185→        private object? ResolveChildWithChildPath(ITrieNodeResolver tree, ref TreePath childPath, int i)
  1186→        {
  1187→            object? childOrRef;
  1188→            SpanSource rlp = _rlp;
  1189→            ref var data = ref _nodeData[i];
  1190→            if (rlp.IsNull)
  1191→            {
  1192→                childOrRef = data;
  1193→            }
  1194→            else
  1195→            {
  1196→                if (data is null)
  1197→                {
  1198→                    // Allows to load children in parallel
  1199→                    ValueRlpStream rlpStream = new ValueRlpStream(rlp);
  1200→                    SeekChild(ref rlpStream, i);
  1201→                    int prefix = rlpStream.ReadByte();
  1202→
  1203→                    switch (prefix)
  1204→                    {
  1205→                        case 0:
  1206→                        case 128:
  1207→                            {
  1208→                                data = childOrRef = _nullNode;
  1209→                                break;
  1210→                            }
  1211→                        case 160:
  1212→                            {
  1213→                                rlpStream.Position--;
  1214→                                Hash256 keccak = rlpStream.DecodeKeccak();
  1215→
  1216→                                TrieNode child = tree.FindCachedOrUnknown(childPath, keccak);
  1217→                                data = childOrRef = child;
  1218→
  1219→                                if (IsPersisted && !child.IsPersisted)
  1220→                                {
  1221→                                    child.CallRecursively(_markPersisted, null, ref childPath, tree, false,
  1222→                                        NullLogger.Instance);
  1223→                                }
  1224→
  1225→                                break;
  1226→                            }
  1227→                        default:
  1228→                            {
  1229→                                rlpStream.Position--;
  1230→                                ReadOnlySpan<byte> fullRlp = rlpStream.PeekNextItem();
  1231→                                TrieNode child = new(NodeType.Unknown, fullRlp.ToArray());
  1232→                                data = childOrRef = child;
  1233→                                break;
  1234→                            }
  1235→                    }
  1236→                }
  1237→                else
  1238→                {
  1239→                    childOrRef = data;
  1240→                }
  1241→            }
  1242→
  1243→            return childOrRef;
  1244→        }
  1245→
  1246→        /// <summary>
  1247→        /// Fast path for trie visitor which visit ranges. Assume node is persisted and has RLP. Does not check for
  1248→        /// data[i] and does not modify it as it assume its not in the cache most of the time.
  1249→        /// </summary>
