  1282→                {
  1283→                    case 0:
  1284→                    case 128:
  1285→                        {
  1286→                            rlpStream.Position++;
  1287→                            output[i] = null;
  1288→                            break;
  1289→                        }
  1290→                    case 160:
  1291→                        {
  1292→                            path.SetLast(i);
  1293→                            Hash256 keccak = rlpStream.DecodeKeccak();
  1294→                            TrieNode child = tree.FindCachedOrUnknown(path, keccak);
  1295→                            chCount++;
  1296→                            output[i] = child;
  1297→
  1298→                            break;
  1299→                        }
  1300→                    default:
  1301→                        {
  1302→                            ReadOnlySpan<byte> fullRlp = rlpStream.PeekNextItem();
  1303→                            TrieNode child = new(NodeType.Unknown, fullRlp.ToArray());
  1304→                            rlpStream.SkipItem();
  1305→                            chCount++;
  1306→                            output[i] = child;
  1307→                            break;
  1308→                        }
  1309→                }
  1310→            }
  1311→
  1312→            path.TruncateOne();
  1313→
  1314→            return chCount;
  1315→        }
  1316→
  1317→        internal void UnresolveChild(int i)
  1318→        {
  1319→            ref var data = ref _nodeData[i];
  1320→            if (IsPersisted)
  1321→            {
  1322→                data = null;
  1323→            }
  1324→            else
  1325→            {
  1326→                if (data is TrieNode childNode)
  1327→                {
  1328→                    if (!childNode.IsPersisted)
  1329→                    {
  1330→                        ThrowNotPersisted();
  1331→                    }
  1332→                    else if (childNode.Keccak is not null) // if not by value node
  1333→                    {
  1334→                        data = childNode.Keccak;
  1335→                    }
  1336→                }
  1337→            }
  1338→
  1339→            [DoesNotReturn, StackTraceHidden]
  1340→            static void ThrowNotPersisted()
  1341→            {
  1342→                throw new InvalidOperationException("Cannot unresolve a child that is not persisted yet.");
  1343→            }
  1344→        }
  1345→
  1346→        public ChildIterator CreateChildIterator()
  1347→        {
  1348→            return new ChildIterator(this);
  1349→        }
  1350→
  1351→        // Allow faster forward child iteration by not re-skipping items on each child seek
  1352→        public ref struct ChildIterator(TrieNode node)
  1353→        {
  1354→            private ValueRlpStream _rlpStream;
  1355→            private int? _currentStreamIndex;
  1356→
  1357→            private object? ResolveChildWithChildPath(ITrieNodeResolver tree, ref TreePath childPath, int i)
  1358→            {
  1359→                object? childOrRef;
  1360→                SpanSource rlp = node._rlp;
  1361→                ref var data = ref node._nodeData[i];
  1362→                if (rlp.IsNull)
  1363→                {
  1364→                    childOrRef = data;
  1365→                }
  1366→                else
  1367→                {
  1368→                    if (data is null)
  1369→                    {
  1370→                        if (_currentStreamIndex.HasValue && _currentStreamIndex <= i)
  1371→                        {
  1372→                            int toSkip = i - _currentStreamIndex.Value;
  1373→                            for (int j = 0; j < toSkip; j++) _rlpStream.SkipItem();
  1374→                            _currentStreamIndex += toSkip;
  1375→                        }
  1376→                        else
  1377→                        {
  1378→                            _rlpStream = new ValueRlpStream(rlp);
  1379→                            _rlpStream.Reset();
  1380→                            _rlpStream.SkipLength();
  1381→                            if (node.IsExtension)
  1382→                            {
  1383→                                _rlpStream.SkipItem();
  1384→                                i--;
  1385→                            }
  1386→                            else
  1387→                            {
  1388→                                for (int j = 0; j < i; j++) _rlpStream.SkipItem();
  1389→                            }
  1390→
  1391→                            _currentStreamIndex = i;
  1392→                        }
  1393→
  1394→                        int prefix = _rlpStream.ReadByte();
  1395→
  1396→                        switch (prefix)
  1397→                        {
  1398→                            case 0:
  1399→                            case 128:
  1400→                                {
  1401→                                    data = childOrRef = _nullNode;
  1402→                                    _currentStreamIndex++;
  1403→                                    break;
  1404→                                }
  1405→                            case 160:
  1406→                                {
  1407→                                    _rlpStream.Position--;
  1408→                                    Hash256 keccak = _rlpStream.DecodeKeccak();
  1409→                                    _currentStreamIndex++;
  1410→
  1411→                                    TrieNode child = tree.FindCachedOrUnknown(childPath, keccak);
  1412→                                    data = childOrRef = child;
  1413→
  1414→                                    if (node.IsPersisted && !child.IsPersisted)
  1415→                                    {
  1416→                                        child.CallRecursively(_markPersisted, null, ref childPath, tree, false,
  1417→                                            NullLogger.Instance);
  1418→                                    }
  1419→
  1420→                                    break;
  1421→                                }
  1422→                            default:
  1423→                                {
  1424→                                    _rlpStream.Position--;
  1425→                                    ReadOnlySpan<byte> fullRlp = _rlpStream.PeekNextItem();
  1426→                                    TrieNode child = new(NodeType.Unknown, fullRlp.ToArray());
  1427→                                    data = childOrRef = child;
  1428→                                    break;
  1429→                                }
  1430→                        }
  1431→                    }
  1432→                    else
  1433→                    {
  1434→                        childOrRef = data;
  1435→                    }
  1436→                }
  1437→
  1438→                return childOrRef;
  1439→            }
  1440→
  1441→            public TrieNode? GetChildWithChildPath(ITrieNodeResolver tree, ref TreePath childPath, int childIndex)
  1442→            {
  1443→                /* extensions store value before the child while branches store children before the value
  1444→                 * so just to treat them in the same way we update index on extensions
  1445→                 */
  1446→                childIndex = node.IsExtension ? childIndex + 1 : childIndex;
  1447→                object childOrRef = ResolveChildWithChildPath(tree, ref childPath, childIndex);
  1448→
  1449→                TrieNode? child;
  1450→                if (ReferenceEquals(childOrRef, _nullNode) || childOrRef is null)
  1451→                {
  1452→                    child = null;
  1453→                }
  1454→                else if (childOrRef is TrieNode childNode)
  1455→                {
  1456→                    child = childNode;
  1457→                }
  1458→                else if (childOrRef is Hash256 reference)
  1459→                {
  1460→                    child = tree.FindCachedOrUnknown(childPath, reference);
  1461→                }
  1462→                else
  1463→                {
  1464→                    // we expect this to happen as a Trie traversal error (please see the stack trace above)
  1465→                    // we need to investigate this case when it happens again
  1466→                    ThrowUnexpectedTypeException(node, childIndex, childOrRef);
  1467→                }
  1468→
  1469→                // pruning trick so we never store long persisted paths
  1470→                // Dont unresolve node of path length <= 4. there should be a relatively small number of these, enough to fit
  1471→                // in RAM, but they are hit quite a lot, and don't have very good data locality.
  1472→                // That said, in practice, it does nothing notable, except for significantly improving benchmark score.
  1473→                if (child?.IsPersisted == true && childPath.Length > 4 && childPath.Length % 2 == 0)
  1474→                {
  1475→                    node.UnresolveChild(childIndex);
  1476→                }
  1477→
  1478→                return child;
  1479→
  1480→                [DoesNotReturn, StackTraceHidden]
  1481→                void ThrowUnexpectedTypeException(TrieNode @this, int childIndex, object childOrRef)
  1482→                {
  1483→                    bool isKeccakCalculated = @this.Keccak is not null && @this.FullRlp.IsNotNull;
  1484→                    bool isKeccakCorrect =
  1485→                        isKeccakCalculated && @this.Keccak == Nethermind.Core.Crypto.Keccak.Compute(@this.FullRlp.Span);
  1486→                    throw new TrieException(
  1487→                        $"Unexpected type found at position {childIndex} of {@this} with {nameof(_nodeData)} of length {@this._nodeData?.Length}. Expected a {nameof(TrieNode)} or {nameof(Keccak)} but found {childOrRef?.GetType()} with a value of {childOrRef}. Keccak calculated? : {isKeccakCalculated}; Keccak correct? : {isKeccakCorrect}");
